-- Bootstrap 6 (tracker C7). Objects created by hand on the hosted production database and needed from 20261002154000_class_owner_returning_policy.sql on.
-- Each is created ONLY IF MISSING: on production nothing changes; on an empty database this supplies them. Generated by scripts/release/build_bootstrap.py.
begin;
set local check_function_bodies = off;

do $boot$ begin if to_regprocedure('public.qb_can_manage_tenant(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_can_manage_tenant(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        public.qb_is_platform_admin()
        or public.qb_tenant_role(p_tenant_id)
           in (
               'OWNER',
               'ADMIN',
               'TENANT_ADMIN',
               'INSTITUTION_ADMIN'
           );
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_is_class_member(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_is_class_member(p_class_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$select quizbox_market.class_allowed(p_class_id) and coalesce((
    select exists (
        select 1
        from public.class_memberships cm
        where cm.class_id = p_class_id
          and cm.student_id = public.qb_current_student_id()
          and lower(cm.status::text) = 'active'
    )),false);$function$
$qb_bootstrap$; end if; end $boot$;

commit;
